{
  "title": "The Glass Diver's Escape",
  "gate_token": "fIGamHbFKnpj2W76xbqNQw",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The ruined city looms under a sickly green sky.",
      "visual_description": "Crumbling spires and collapsed walls stretch under a green sky. Tattered banners hang from broken flagpoles. The glass diver stands at the edge, his helmet reflecting the ruins.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara unfolds a map on a fallen pillar.",
      "visual_description": "Mara the cartographer spreads a weathered map over a mossy stone pillar, her compass glinting. The tin fox sits beside her, tail ticking.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp flickers a warning from a broken window.",
      "visual_description": "In a shattered window frame, the oracle lamp glows with a single fiery eye. Its flame wavers as it speaks, casting long shadows.",
      "characters": ["oracle_lamp"]
    },
    {
      "scene_number": 4,
      "caption": "The group approaches the sealed castle gates.",
      "visual_description": "Great iron gates, rusted and entwined with thorny vines, block the entrance. The glass diver peers through a gap while Mara checks her map.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "Inside the gatehouse, a sleeping tax collector snores.",
      "visual_description": "A stout figure slumps over a ledger book, stamps stuck to his sleeves. Dust motes dance in a sliver of light from a high window.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox scouts ahead through a cracked archway.",
      "visual_description": "The small metal fox pads silently through an arched passage, its blue glass eyes scanning for danger. Moss covers the cobblestones.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara reads a faded sign pointing to the cursed tower.",
      "visual_description": "Beneath a guttering torch, Mara traces the words on an old stone sign. The tower looms in the background, twisted and dark.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The glass diver swims through a mirror into the tower base.",
      "visual_description": "The glass diver presses his helmet against a tall mirror, then passes through its surface like water, ripples distorting his reflection.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Inside, the glass diver finds a room of old royal banners.",
      "visual_description": "A circular room hung with moth-eaten banners bearing faded crests. Dusty light filters through a grime-coated window.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The tin fox triggers a hidden pressure plate.",
      "visual_description": "The fox steps on a loose stone; a click echoes. A section of wall grinds open, revealing a dark passage.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "Armored patrols march through the courtyard below.",
      "visual_description": "From a high balcony, the group watches figures in dented armor clank across the courtyard, their visors down, swords drawn.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The sleeping tax collector wakes briefly and stamps a form.",
      "visual_description": "The collector stirs, blinks, stamps a paper, and pushes it toward the group before falling asleep again, head hitting the ledger.",
      "characters": ["sleeping_tax_collector", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door with a puzzle lock blocks the path.",
      "visual_description": "A stone door inscribed with glowing runes and a circular lock. The tin fox sniffs at the runes while Mara studies symbols.",
      "characters": ["mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp whispers the door's riddle.",
      "visual_description": "The lamp's flame brightens as it speaks, casting rune shadows on the door. Mara turns the lock with a click.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The door opens onto a bridge over a chasm.",
      "visual_description": "A narrow stone bridge spans a deep chasm, mist rising from below. The far side holds a faint light. The glass diver steps forward.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 16,
      "caption": "Armored patrols gather at the bridge's near end.",
      "visual_description": "Figures in dented armor march onto the bridge's entrance, their footsteps echoing. The group hurries across the span.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The glass diver smashes a mirror to slow the pursuit.",
      "visual_description": "The glass diver shatters a standing mirror on the bridge, sending shards cascading. The armored figures hesitate at the broken glass.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 18,
      "caption": "The group escapes through an archway into the wild.",
      "visual_description": "Beyond the bridge, the group passes under a crumbling arch into misty fields. The oracle lamp dims as dawn breaks.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

